using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OperationsRequests.Data;using OperationsRequests.Domain;namespace OperationsRequests.Pages.Admin;[Authorize(Roles="PlatformAdmin")]public class UsersModel(ApplicationDbContext db,UserManager<ApplicationUser> users):PageModel{public List<ApplicationUser> Users{get;set;}=[];public List<Country> Countries{get;set;}=[];public List<Territory> Territories{get;set;}=[];public List<Site> Sites{get;set;}=[];[BindProperty]public UserInput Input{get;set;}=new();public sealed class UserInput{public string Email{get;set;}="";public string DisplayName{get;set;}="";public string Password{get;set;}="";public string Role{get;set;}=Roles.StaffMember;public int? CountryId{get;set;}public int? TerritoryId{get;set;}public int? SiteId{get;set;}}public async Task OnGetAsync()=>await Load();public async Task<IActionResult> OnPostAssignAsync(string id,string role,int? countryId,int? territoryId,int? siteId){var u=await users.FindByIdAsync(id);if(u is null||!Roles.All.Contains(role))return NotFound();var old=string.Join(',',await users.GetRolesAsync(u));var site=siteId is null?null:await db.Sites.Include(x=>x.Territory).SingleOrDefaultAsync(x=>x.Id==siteId);var terr=territoryId is null?null:await db.Territories.FindAsync(territoryId);var ok=role==Roles.PlatformAdmin&&countryId is null&&territoryId is null&&siteId is null||role==Roles.CountryOpsManager&&countryId is not null&&territoryId is null&&siteId is null||role==Roles.TerritoryManager&&terr?.CountryId==countryId&&siteId is null||((role==Roles.SiteManager||role==Roles.StaffMember)&&site?.TerritoryId==territoryId&&site?.Territory.CountryId==countryId);if(!ok)return BadRequest("Invalid organisation assignment.");await users.RemoveFromRolesAsync(u,await users.GetRolesAsync(u));await users.AddToRoleAsync(u,role);u.CountryId=countryId;u.TerritoryId=territoryId;u.SiteId=siteId;await users.UpdateAsync(u);db.AuditEvents.Add(new AuditEvent{Action="OrgAssignmentChanged",ActorId=(await users.GetUserAsync(User))!.Id,ActorName="Platform Admin",Note=$"{u.Email}: {old} -> {role}"});await db.SaveChangesAsync();return RedirectToPage();}public async Task<IActionResult> OnPostToggleAsync(string id){var u=await users.FindByIdAsync(id);if(u is null)return NotFound();u.IsActive=!u.IsActive;await users.UpdateSecurityStampAsync(u);await users.UpdateAsync(u);db.AuditEvents.Add(new AuditEvent{Action=u.IsActive?"UserActivated":"UserDeactivated",ActorName="Platform Admin",Note=u.Email});await db.SaveChangesAsync();return RedirectToPage();}async Task Load(){Users=await users.Users.OrderBy(x=>x.Email).ToListAsync();Countries=await db.Countries.ToListAsync();Territories=await db.Territories.ToListAsync();Sites=await db.Sites.Include(x=>x.Territory).ThenInclude(x=>x.Country).ToListAsync();}}

